+<body><header class="top"><div class="brand">giant<span>hearts</span></div><div class="top-right"><span>✦ &nbsp;A little love goes a long way</span><span class="save-pill">● &nbsp;Progress saved</span></div></header>
+<main class="layout"><div class="hero"><div><div class="eyebrow">Your very big love story</div><h1>Room for two. And then some.</h1><p>Get to know your giant, one sweet moment at a time.</p></div><div class="days">YOUR STORY<strong>Day <span id="day">1</span></strong></div></div>
+<div class="columns"><section class="scene-card"><div class="scene"><div class="sun"></div><div class="cloud">☁</div><div class="scene-label">THE QUIET SIDE OF TOWN &nbsp;·&nbsp; GOLDEN HOUR</div><div class="figures"><div class="person" title="You"></div><div class="man" id="man"><div class="hair"></div><div class="head"></div><div class="neck"></div><div class="arm left"></div><div class="arm right"></div><div class="torso"></div><div class="shorts"></div><div class="leg"></div><div class="leg two"></div><div class="shoe"></div><div class="shoe two"></div></div></div><div class="scene-caption" id="caption">A peaceful evening with your favorite giant.</div><div class="overlay-toast" id="toast"></div></div><div class="scene-bottom"><div><strong id="sceneTitle">A gentle kind of giant</strong><span>He's glad you're here.</span></div><button class="compare-btn" onclick="compare()">↕ &nbsp;Compare our heights</button></div></section>
+<aside class="side"><section class="side-card"><div class="guy-head"><div><div class="eyebrow">Your giant</div><h2 id="name">Milo</h2></div><span class="tag" id="trait">♥ Gentle</span></div><p class="profile-desc" id="desc">A broad-shouldered, handsome jock with warm eyes and an easy smile. He's careful with his enormous strength—and always makes you feel safe.</p><div class="stat"><div class="stat-label"><span>HIS HEIGHT</span><strong id="heightStat">8 ft</strong></div><div class="bar"><div class="fill" id="heightBar" style="width:8%"></div></div></div><div class="stat"><div class="stat-label"><span>HAPPINESS</span><strong id="happyVal">72%</strong></div><div class="bar"><div class="fill aff" id="happyBar" style="width:72%"></div></div></div><div class="stat"><div class="stat-label"><span>YOUR BOND</span><strong id="bondVal">12%</strong></div><div class="bar"><div class="fill" id="bondBar" style="width:12%;background:var(--gold)"></div></div></div></section>
+<section class="side-card"><h3 class="actions-title">Make his day</h3><div class="actions"><button class="action" onclick="act('feed')"><span class="emoji">🍓</span><b>Bring a snack</b><small>He worked up an appetite</small></button><button class="action" onclick="act('cuddle')"><span class="emoji">🫂</span><b>Cuddle close</b><small>His favorite kind of cozy</small></button><button class="action" onclick="act('kiss')"><span class="emoji">💋</span><b>Steal a kiss</b><small>He bends down to meet you</small></button><button class="action" onclick="act('compliment')"><span class="emoji">✨</span><b>Say something sweet</b><small>Tell him what you adore</small></button></div></section>
+<section class="side-card"><div class="eyebrow">A bigger love</div><div class="growth-row"><strong>Choose his height</strong><span>7 ft — 100 ft</span></div><input aria-label="Choose giant's height" class="slider" id="heightSlider" type="range" min="7" max="100" value="8" oninput="previewHeight(this.value)"><div class="range-labels"><span>7 ft · tall</span><span>100 ft · colossal</span></div><button class="grow-button" onclick="grow()">✦ &nbsp;Grow with his consent</button><div class="switcher"><button class="active" onclick="choose('Milo','Gentle',this)">Milo · gentle</button><button onclick="choose('Jude','Confident',this)">Jude · confident</button><button onclick="choose('Ash','Playful',this)">Ash · playful</button></div></section></aside></div><div class="footer">A cozy, <span>consensual</span> romance about connection at any scale. &nbsp;·&nbsp; All characters are adults.</div></main>
+<script>
+const defaults={};let height=Number(localStorage.getItem('gh-height'))||8,bond=Number(localStorage.getItem('gh-bond'))||12,happy=Number(localStorage.getItem('gh-happy'))||72,day=Number(localStorage.getItem('gh-day'))||1;let guy=localStorage.getItem('gh-name')||'Milo',style=localStorage.getItem('gh-style')||'Gentle';
+const profiles={Milo:{trait:'Gentle',color:'#536f65',desc:'A broad-shouldered, handsome jock with warm eyes and an easy smile. He’s careful with his enormous strength—and always makes you feel safe.'},Jude:{trait:'Confident',color:'#61536f',desc:'A handsome, athletic former college quarterback: self-assured, attentive, and surprisingly soft-hearted with someone he trusts.'},Ash:{trait:'Playful',color:'#786044',desc:'A tall, handsome gym regular with a mischievous grin. He loves a little friendly teasing and knows exactly when to be gentle.'}};
+function apply(){height=Number(height);document.getElementById('name').textContent=guy;document.getElementById('trait').textContent='♥ '+profiles[guy].trait;document.getElementById('desc').textContent=profiles[guy].desc;document.querySelector('.torso').style.setProperty('--shirt',profiles[guy].color);document.getElementById('heightStat').textContent=height+' ft';document.getElementById('heightBar').style.width=Math.min(100,height)+'%';document.getElementById('happyVal').textContent=happy+'%';document.getElementById('happyBar').style.width=happy+'%';document.getElementById('bondVal').textContent=bond+'%';document.getElementById('bondBar').style.width=bond+'%';document.getElementById('day').textContent=day;document.getElementById('sceneTitle').textContent=height>=40?'A truly towering kind of giant':height>=15?'A wonderfully big kind of giant':style==='Gentle'?'A gentle kind of giant':'A '+style.toLowerCase()+' kind of giant';document.getElementById('heightSlider').value=height;let pct=(height-7)/93*100;document.getElementById('heightSlider').style.setProperty('--pct',pct+'%');let h=Math.min(380,220+Math.log(height/7)*74);document.getElementById('man').style.setProperty('--guy-height',h+'px');document.getElementById('man').style.setProperty('--growth',Math.min(1.26,1+Math.log(height/8)*.12));document.querySelectorAll('.switcher button').forEach(b=>b.classList.toggle('active',b.textContent.startsWith(guy)));localStorage.setItem('gh-height',height);localStorage.setItem('gh-name',guy);localStorage.setItem('gh-bond',bond);localStorage.setItem('gh-happy',happy);localStorage.setItem('gh-day',day);localStorage.setItem('gh-style',style)}
+function previewHeight(v){document.getElementById('heightStat').textContent=v+' ft';let pct=(v-7)/93*100;document.getElementById('heightSlider').style.setProperty('--pct',pct+'%')}
+function grow(){height=Number(document.getElementById('heightSlider').value);day++;happy=Math.min(100,happy+3);apply();toast(height>=40?'The whole skyline has a new favorite view.':height>=15?'He ducks under the clouds and grins.':'He stretches up, taller than ever.');document.getElementById('caption').textContent=height>=40?`At ${height} feet, the city feels like a little neighborhood.`:`Now ${height} feet tall—and still looking down just for you.`}
+function act(type){day++;bond=Math.min(100,bond+(type==='cuddle'?9:7));happy=Math.min(100,happy+(type==='feed'?14:8));apply();let messages={feed:'A snack, shared between sweethearts.',cuddle:'He wraps you in the gentlest hug.',kiss:'He leans down. You meet him halfway.',compliment:'His smile says it all.'};toast(messages[type]);document.getElementById('caption').textContent=messages[type]}
+function choose(name,mood,button){guy=name;style=mood;apply();toast(name+' is happy you chose him.');document.getElementById('caption').textContent='A new beginning with '+name+'.'}
+function compare(){let relative=height<=8?'He’s just a little taller than you.':height<15?'You reach about his waist.':height<35?'You’re a tiny figure beside him.':'You could fit in the palm of his hand.';toast(`You: 5′8″  ·  ${guy}: ${height} ft`);document.getElementById('caption').textContent=relative}
+function toast(text){let el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}apply();
+</script></body></html>
*** End Patch

